          last_market_fetch: "2026-02-17T10:00:00Z",
          uptime_hours: 24.5,
          wallet_balance: null,
          wallet_balance_error: null,
        },
        error: null,
      } as ReturnType<typeof useSystemStatus>);

      const { default: Index } = await import("./Index");
      render(<Index />, { wrapper: createWrapper() });

      expect(screen.getByText("+$15.50")).toBeInTheDocument();
    });

    it("should display today PnL with negative values", async () => {
      const { useOverview, useSystemStatus } = await import("@/hooks/useStatistics");
      vi.mocked(useOverview).mockReturnValue({
        isLoading: false,
        data: {
          current_capital: 190,
          initial_capital: 200,
          total_pnl: -10,
          total_pnl_pct: -0.05,
          win_rate: 0.5,
          total_trades: 10,
          winning_trades: 5,
          losing_trades: 5,
          open_positions: 2,
          trading_enabled: true,
          mode: "PAPER",
          wallet_balance: null,
          wallet_balance_error: null,
        },
        error: null,
      } as ReturnType<typeof useOverview>);
      vi.mocked(useSystemStatus).mockReturnValue({
        isLoading: false,
        data: {
          trading_enabled: true,
          mode: "PAPER",
          current_capital: 190,
          daily_pnl: -5.25,
          open_positions: 2,
          consecutive_losses: 2,
          reduced_mode: false,
          last_market_fetch: "2026-02-17T10:00:00Z",
          uptime_hours: 24.5,
          wallet_balance: null,
          wallet_balance_error: null,
        },
        error: null,
      } as ReturnType<typeof useSystemStatus>);

      const { default: Index } = await import("./Index");
      render(<Index />, { wrapper: createWrapper() });

      expect(screen.getByText("$-5.25")).toBeInTheDocument();
    });

    it("should display win rate percentage", async () => {
      const { useOverview, useSystemStatus } = await import("@/hooks/useStatistics");
      vi.mocked(useOverview).mockReturnValue({
        isLoading: false,
        data: {
